from typing import Any, Dict, List, Tuple
from blocks.base_python_block import WFEngineTaskResult
from blocks.types import BlockInputs
from blocks.base_python_block import Block, WFEngineTask


# Used to deserialize json inputs by the CCB
class CustomCodeBlockProxyInputs(BlockInputs):
    flow_run: Any
    get_submissions_response: Any

def _prep_output_data(flow_run: dict, get_submissions_response: dict) -> dict:
    submissions_in_response = get_submissions_response.get('results', [])
    submission = None if not submissions_in_response else submissions_in_response[0]
    return {'flow_run': flow_run, 'submission': submission}



def process_task(
    proxy: Block, task: WFEngineTask[CustomCodeBlockProxyInputs]
) -> WFEngineTaskResult:
    return _prep_output_data(**task.inputData.dict())
